import { hexToBigInt, namehash } from 'viem'
import { config } from '@/lib/config'
import { activeChainSlug } from '../web3/chain'

export const DOMAIN_IMAGE_URL = `${config.ensMetadataUrl}/${activeChainSlug}/${config.ensRegistrar}`
export const WRAPPED_DOMAIN_IMAGE_URL = `${config.ensMetadataUrl}/${activeChainSlug}/${config.ensNameWrapper}`
export const DOMAIN_IMAGE_URL_V2 = `${config.ensMetadataUrl}/${activeChainSlug}/${config.ensV2Registrar}`

/**
 * Name image generated by our own /api/og/ens-name route. The metadata services
 * (metadata.ethid.org, metadata.ens.domains) answer "unsupported contract" for every ENSv2
 * contract as of 2026-10-24, so ENSv2 names fall back to this. Relative path: prefix the
 * request origin when an absolute URL is needed (OG routes).
 */
export const localNameImagePath = (name: string, expiryDate?: string | null) => {
  const expires = expiryDate ? new Date(expiryDate).getTime() : ''
  return `/api/og/ens-name/${hexToBigInt(namehash(name)).toString()}?name=${encodeURIComponent(name)}&expires=${encodeURIComponent(expires)}`
}
